#!/bin/sh
# Build a self-contained PKI for EAP-TLS testing.
#
# Enterprise SSIDs cannot be tested with a passphrase: the station needs a real
# identity, and EAP-TLS needs a certificate chain that both ends trust. Buying
# or borrowing one would make the bench unreproducible, so the testbed issues
# its own — a CA, a server certificate for FreeRADIUS, and a client certificate
# for the station.
#
# Everything here is deliberately throwaway: short-lived, generated on the
# bench, and never reused anywhere. The key material is regenerated by running
# this script again, and is gitignored so a checkout cannot inherit somebody
# else's private keys.
#
# Usage:  ./make-pki.sh [output-dir]     (default: ./out)
set -eu

OUT="${1:-$(dirname "$0")/out}"
DAYS="${PKI_DAYS:-825}"          # inside the 825-day cap clients enforce
SUBJ_BASE="${PKI_SUBJ_BASE:-/C=US/ST=Lab/L=Bench/O=80211 Testing Framework}"
CLIENT_CN="${PKI_CLIENT_CN:-testuser}"
SERVER_CN="${PKI_SERVER_CN:-radius.bench.local}"
P12_PASS="${PKI_P12_PASS:-whatever}"

command -v openssl >/dev/null || { echo "openssl is required"; exit 1; }
mkdir -p "$OUT"
cd "$OUT"

echo "==> certificate authority"
openssl req -x509 -newkey rsa:2048 -nodes -keyout ca.key -out ca.pem \
    -days "$DAYS" -sha256 \
    -subj "${SUBJ_BASE}/CN=80211 Bench Root CA" 2>/dev/null

# The server certificate needs the TLS Web Server EKU. wpa_supplicant checks it,
# and a certificate without it is rejected with an error that looks like a
# handshake fault rather than a policy one.
cat > server.ext <<EXT
basicConstraints = CA:FALSE
keyUsage = digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth
subjectAltName = DNS:${SERVER_CN}
EXT

echo "==> RADIUS server certificate (${SERVER_CN})"
openssl req -newkey rsa:2048 -nodes -keyout server.key -out server.csr \
    -subj "${SUBJ_BASE}/CN=${SERVER_CN}" 2>/dev/null
openssl x509 -req -in server.csr -CA ca.pem -CAkey ca.key -CAcreateserial \
    -out server.pem -days "$DAYS" -sha256 -extfile server.ext 2>/dev/null

cat > client.ext <<EXT
basicConstraints = CA:FALSE
keyUsage = digitalSignature, keyEncipherment
extendedKeyUsage = clientAuth
EXT

echo "==> station client certificate (CN=${CLIENT_CN})"
openssl req -newkey rsa:2048 -nodes -keyout client.key -out client.csr \
    -subj "${SUBJ_BASE}/CN=${CLIENT_CN}" 2>/dev/null
openssl x509 -req -in client.csr -CA ca.pem -CAkey ca.key -CAcreateserial \
    -out client.pem -days "$DAYS" -sha256 -extfile client.ext 2>/dev/null

# Bundled form, for clients that want one file.
openssl pkcs12 -export -out client.p12 -inkey client.key -in client.pem \
    -certfile ca.pem -passout "pass:${P12_PASS}" 2>/dev/null

# FreeRADIUS insists on DH parameters for EAP and refuses to start without
# them. 2048-bit generation is slow; the group is not secret, so a named group
# is both faster and no weaker.
echo "==> DH parameters"
openssl dhparam -dsaparam -out dh 2048 2>/dev/null

rm -f server.csr client.csr server.ext client.ext

# The CA key is what would let someone mint new identities, so it stays
# root-only along with the client key. The *server* key has to be readable by
# the freerad user the daemon drops to, or EAP fails to initialise with a bare
# "Permission denied" that looks like a certificate problem rather than a
# filesystem one. It is a disposable bench key with no value outside this lab.
chmod 600 ca.key client.key client.p12
chmod 644 server.key

echo
echo "PKI written to $OUT"
openssl x509 -in server.pem -noout -subject -issuer -dates | sed 's/^/  server: /'
openssl x509 -in client.pem -noout -subject -issuer -dates | sed 's/^/  client: /'
echo "  client bundle password: ${P12_PASS}"
